// The settings schema, generated by asking the installed Ghostty to describe
// itself: `+show-config --default --docs` emits every option with its default
// and documentation. Because the source is the binary that will consume the
// config, the schema's option list can never drift across upgrades; only the
// type-inference heuristics here can be wrong, and their failure mode is a
// plain text input in the form, never wrong data.

import { runAction, versionLine } from "./ghostty.mjs";
import { parse } from "./config-model.mjs";

// Keys with append semantics (repeated lines accumulate instead of override).
// From the config-format research plus the repeated keys observed in the
// default dump itself.
const LIST_KEYS = new Set([
  "palette",
  "keybind",
  "command-palette-entry",
  "font-family",
  "font-family-bold",
  "font-family-italic",
  "font-family-bold-italic",
  "font-feature",
  "font-codepoint-map",
  "font-variation",
  "env",
  "config-file",
  "custom-shader",
]);

const CATEGORIES = [
  ["font-", "Fonts"],
  ["freetype-", "Fonts"],
  ["adjust-", "Fonts"],
  ["theme", "Colors"],
  ["background", "Colors"],
  ["foreground", "Colors"],
  ["palette", "Colors"],
  ["selection-", "Colors"],
  ["minimum-contrast", "Colors"],
  ["bold-", "Colors"],
  ["faint-", "Colors"],
  ["split-divider-color", "Colors"],
  ["unfocused-split-", "Colors"],
  ["cursor-", "Cursor"],
  ["mouse-", "Mouse"],
  ["click-", "Mouse"],
  ["scrollback-", "Terminal"],
  ["shell-integration", "Shell"],
  ["command", "Shell"],
  ["initial-command", "Shell"],
  ["working-directory", "Shell"],
  ["env", "Shell"],
  ["window-", "Window"],
  ["fullscreen", "Window"],
  ["maximize", "Window"],
  ["title", "Window"],
  ["resize-", "Window"],
  ["macos-", "macOS"],
  ["gtk-", "Linux/GTK"],
  ["x11-", "Linux/GTK"],
  ["linux-", "Linux/GTK"],
  ["clipboard-", "Clipboard"],
  ["copy-", "Clipboard"],
  ["keybind", "Keybinds"],
  ["quick-terminal-", "Quick Terminal"],
];

function categoryFor(key) {
  for (const [prefix, cat] of CATEGORIES) {
    if (key === prefix || key.startsWith(prefix)) return cat;
  }
  return "Other";
}

function extractEnum(doc) {
  if (!/valid values/i.test(doc)) return null;
  const vals = [...doc.matchAll(/^\s*\*\s*`([^`\s]+)`/gm)].map((m) => m[1]);
  return vals.length >= 2 ? vals : null;
}

function inferType(entry) {
  if (entry.list) return "list";
  const def = entry.default;
  if (def === "true" || def === "false") return "boolean";
  if (def !== "" && def !== null && !Number.isNaN(Number(def))) return "number";
  // Enum beats color: several *-color keys take named values (background,
  // extend, X11 names) where a doc-bulleted value list is the real contract.
  if (entry.enumValues) return "enum";
  if (/^#?[0-9a-fA-F]{6}$/.test(def) || /-color$/.test(entry.key)) return "color";
  return "string";
}

function platformOf(doc) {
  if (/GTK only|Linux only/i.test(doc)) return "linux";
  if (/macOS only/i.test(doc)) return "macos";
  return null;
}

let cached = null;

export function buildSchema() {
  if (cached) return cached;
  const dump = runAction(["+show-config", "--default", "--docs"]);
  const model = parse(dump);

  let docBuf = [];
  const byKey = new Map();
  for (const e of model.entries) {
    if (e.kind === "comment") {
      docBuf.push(e.raw.replace(/^#\s?/, ""));
    } else if (e.kind === "blank") {
      docBuf = [];
    } else if (e.kind === "pair") {
      if (byKey.has(e.key)) {
        byKey.get(e.key).defaults.push(e.value);
      } else {
        byKey.set(e.key, {
          key: e.key,
          defaults: [e.value],
          doc: docBuf.join("\n").trim(),
          list: LIST_KEYS.has(e.key),
          category: categoryFor(e.key),
        });
      }
      docBuf = [];
    }
  }

  const options = [...byKey.values()].map((o) => {
    const entry = {
      ...o,
      default: o.list ? null : o.defaults[0] ?? "",
      enumValues: extractEnum(o.doc),
      platform: platformOf(o.doc),
    };
    entry.type = inferType(entry);
    if (entry.type !== "enum") entry.enumValues = null;
    return entry;
  });

  cached = { ghosttyVersion: versionLine(), options };
  return cached;
}
